(function(){
  const oldOpen=openGodownOpeningForm;
  openGodownOpeningForm=function(id){const out=oldOpen.apply(this,arguments);setTimeout(()=>{const form=$('#godownOpeningForm');if(!form)return;if(!form.querySelector('[name="godown_partType"]')){const wrap=document.createElement('label');wrap.className='field';wrap.innerHTML='<span>Part Type</span><select name="godown_partType"><option value="Genuine">Genuine</option><option value="Aftermarket">Aftermarket</option></select>';const grid=form.querySelector('.formgrid');grid?.prepend(wrap);const part=id?find('parts',id):null;wrap.querySelector('select').value=part?.partType||'Genuine'}const nameInput=form.querySelector('[name="godown_name"]');if(nameInput&&!nameInput.getAttribute('list')){const list=document.createElement('datalist');list.id='godownPartNames';list.innerHTML=(db.parts||[]).map(p=>'<option value="'+esc(p.name)+'" label="'+esc(p.id+' — '+(p.partType||'Genuine'))+'"></option>').join('');form.append(list);nameInput.setAttribute('list',list.id);nameInput.placeholder='Select or enter part name'}const model=form.querySelector('[name="godown_vehicleModel"]');if(model&&!model.getAttribute('list')){const list=document.createElement('datalist');list.id='godownVehicleModels';list.innerHTML=[...new Set((db.parts||[]).map(p=>p.vehicleModel).filter(Boolean))].sort().map(v=>'<option value="'+esc(v)+'"></option>').join('');form.append(list);model.setAttribute('list',list.id);model.placeholder='Select or enter vehicle model'}if(typeof bindTypedSku==='function')bindTypedSku(form)},0);return out};
})();
